  const MODULE_ID = 'tools';

  // THE SHARED CALCULATORS. A script of its own so that getting a calculator
  // does not mean installing an unrelated module, and so Core stays lean —
  // every tool here is a string of ~80-100 KB, and Core loads for every user.
  // It registers links, not a module: there is nothing running and nothing to
  // persist, so an on/off switch would be a dead control.
  //
  // A tool that needs one module's live observations stays with that module
  // (Party Gold ROI, in pet-slot-alarm.js) until the import layer can supply
  // them independently. Everything else belongs here.
  void MODULE_ID;

  // ---- shared tools: standalone pages, opened in their own tab ----
  //
  // NOT a module. There is nothing running and nothing to persist, so an
  // enable/disable switch would be a dead control — see Core's `tools`
  // registry comment. It appears under "Tools" in the dropdown.
  //
  // WHY A NEW TAB IS THE RIGHT SHAPE, not a compromise: a second tab gets its
  // own main thread, so a heavy interactive page costs the game page nothing.
  // INSTRUMENTATION.md §2's throttling constraint is about BACKGROUND work —
  // and a calculator the user is looking at is by definition in the
  // foreground, while a backgrounded one being throttled is exactly what you
  // want. This is the one place where "run it in the browser" is strictly
  // better than routing through the core.
  //
  // The payload is embedded by the build (no network, no hosting, versioned
  // with the script) and turned into a blob URL at click time rather than at
  // load, so the ~40KB string is only ever materialised as a URL if the user
  // actually opens it.
  //
  // The payload is REBUILT on each open rather than cached, because a live
  // snapshot of your slot levels / character level / party is prepended to it
  // and a cached URL would hand over whatever was true the first time. The
  // previous blob is revoked first, so exactly one is ever alive - which was
  // the reason the URL was cached in the first place.
  // Exploration Ceiling — highest Village Exploration level a 25-member
  // roster can still clear all 40 monsters. Unlike Party Gold ROI above,
  // this one carries NO live snapshot yet: reading all 25 members' real
  // stats needs a roster scrape this repo hasn't built (see the tool's own
  // Formulas panel, tagged OPEN) — Game live mode inside it is a stub until
  // then, so there is nothing live worth prepending. The blob is still
  // rebuilt fresh on each open (not cached at module load) for the same
  // reason as roiUrl: keeps this consistent if a live snapshot is added
  // later, and costs nothing today.
  // Every opener goes through here. Core.toolHtml (Core v12) prepends the
  // player's theme, developer-info and tool-font settings as
  // window.AWOO_APPEARANCE, plus any `extra` globals, AFTER the doctype the
  // build gives every tool — a <script> ahead of the doctype drops the page
  // into quirks mode. An older Core has no toolHtml; the tool then opens in
  // its own default theme, and `extra` still goes in at the same place.
  function toolPayload(html, extra) {
    if (typeof Core.toolHtml === 'function') return Core.toolHtml(html, extra);
    const body = Object.keys(extra || {})
      .map((k) => `window.${k}=${JSON.stringify(extra[k]).replace(/</g, '\\u003c')};`).join('');
    if (!body) return html;
    return html.replace(/^(<!doctype html>\n<meta charset="utf-8">\n)?/i, (head) => head + '<script>' + body + '<' + '/script>\n');
  }

  let explorationCeilingUrl = null;
  Core.registerLink({
    id: 'exploration-ceiling',
    label: 'Exploration Ceiling',
    open() {
      if (explorationCeilingUrl) { try { URL.revokeObjectURL(explorationCeilingUrl); } catch (e) { /* ignore */ } }
      explorationCeilingUrl = URL.createObjectURL(new Blob([toolPayload(AWOO_TOOL_EXPLORATION_CEILING)], { type: 'text/html' }));
      return explorationCeilingUrl;
    },
  });

  // Cost Tables — what every upgradeable system costs, level by level, with
  // the cumulative from wherever the player currently is. Fifteen subjects in
  // one page rather than fifteen tools: they share one table shape, one set of
  // settings and one Formula & source panel, and splitting them would mean
  // fifteen links in the dropdown for one question ("what does the next one
  // cost"). Carries no live snapshot yet — every current level is typed in,
  // and the page's profile-sync card says so plainly (R46/R48 groundwork is
  // written and dormant, see ARTIFACT_STYLE_GUIDE.md Part III).
  let costTablesUrl = null;
  Core.registerLink({
    id: 'cost-tables',
    label: 'Cost Tables',
    open() {
      if (costTablesUrl) { try { URL.revokeObjectURL(costTablesUrl); } catch (e) { /* ignore */ } }
      costTablesUrl = URL.createObjectURL(new Blob([toolPayload(AWOO_TOOL_COST_TABLES)], { type: 'text/html' }));
      return costTablesUrl;
    },
  });

  // Sculpture Stat Optimizer — optimal sculpture grid split for Stat Rate % vs
